List<String> separateParenGroups(String parenString) {
  if (parenString.isEmpty || !RegExp(r'^[\(\)]+$').hasMatch(parenString)) {
    return [];
  }

  List<List<int>> pairs = <List<int>>[];
  int depth = 0;

  for (int i = 0; i < parenString.length; ++i) {
    String c = parenString[i];
    switch(c){
      case '(':
        // push new pair on stack with current index as start point
        pairs.add(<int>[i, -1]);
        break;

      default: 
        assert(')' == c);

        if (-1 != depth--) {  
          final lastPairIndex = --pairs.last[1];    

          while(pairs.isNotEmpty && (--depth >= 0))
