int primeFib(int n) {
  bool isPrime(int p) {
    if (p < 2) {
      return false;
    }
    for (int k = 2; k < min(sqrt(p).toInt() + 1, p - 1); k++) {
      if (p % k == 0) {
        return false;
      }
